part('engine','ENGINE BLOCK',4.6,2.6);part('wheels','SET OF FOUR WHEELS',-4.9,1.7);part('battery','BATTERY',5.7,5);part('fuel','FUEL CAN',-5.3,5.4);
// A tiny destination peeking through the trees: the lakeside summer shop.
box(scene,'shop',[10,1.7,-408],[7,3.4,6],mat(0xe5d6b3));box(scene,'shop roof',[10,3.55,-408],[7.8,.35,6.8],mat(0xb24e32));box(scene,'shop door',[10,1,-404.94],[1.2,2,.08],mats.wood);box(scene,'shop window',[8.3,2,-404.93],[1.5,1.2,.08],mats.glass);box(scene,'shop window',[11.7,2,-404.93],[1.5,1.2,.08],mats.glass);
for(const x of [7.4,12.6]){cylinder(scene,[x,.75,-401],.28,.28,1.5,mats.red,[Math.PI/2,0,0]);box(scene,'pump head',[x,1.4,-401],[.65,.45,.28],mats.white);}
box(scene,'shop sign post',[4,2.3,-365],[.18,4.6,.18],mats.wood);
const signCanvas=document.createElement('canvas');signCanvas.width=512;signCanvas.height=192;const sc=signCanvas.getContext('2d');sc.fillStyle='#20372b';sc.fillRect(0,0,512,192);sc.fillStyle='#f0d7a2';sc.font='bold 54px sans-serif';sc.fillText('KESÄKAUPPA',25,78);sc.font='30px monospace';sc.fillText('LAKESIDE  ·  400 m',27,137);const signTex=new THREE.CanvasTexture(signCanvas);const sign=new THREE.Mesh(new THREE.PlaneGeometry(3.6,1.35),new THREE.MeshBasicMaterial({map:signTex}));sign.position.set(4,3.3,-365);scene.add(sign);
// First-person explorer and driving state
const player={x:0,z:7,yaw:0,pitch:-.03};let mode='walk',started=false,fuel=100,distance=0,toastTimer=0,won=false;
const flags={engine:false,wheels:false,battery:false,fuel:false};const keys={};
function say(text){$('#toast').textContent=text;$('#toast').classList.add('show');toastTimer=2.2}
function completed(){return Object.values(flags).every(Boolean)}
function refreshObjective(){const n=Object.values(flags).filter(Boolean).length;if(!completed()){$('#objectiveTitle').textContent=`Get the old Lintukoto running  ·  ${n}/4`;
 const next=['engine','wheels','battery','fuel'].filter(k=>!flags[k]).map(k=>({engine:'engine block',wheels:'four wheels',battery:'battery',fuel:'a little fuel'}[k]));$('#objectiveSub').textContent=`Find ${next.join(', ').replace(/, ([^,]*)$/, ' and $1')} around the garage, then hop in.`;}
 else{$('#objectiveTitle').textContent=won?'You made it to the lake!':'Take the long way';$('#objectiveSub').textContent=won?'A perfect little summer drive. Your uncle would be proud.':'Drive down the forest road to the lakeside shop. It is about 400 metres away.'}}
function nearest(){if(mode==='drive')return{kind:'car',distance:0};let best=null,bd=Infinity;for(const p of parts){if(flags[p.userData.type])continue;const d=Math.hypot(player.x-p.position.x,player.z-p.position.z);if(d<bd){bd=d;best={kind:'part',obj:p,distance:d}}}const dc=Math.hypot(player.x-car.position.x,player.z-car.position.z);if(dc<bd){best={kind:'car',distance:dc};bd=dc}return best}
function interact(){if(mode==='drive'){mode='walk';player.x=car.position.x+2.2;player.z=car.position.z+.4;say('Back on your own two feet.');return}
 const n=nearest();if(!n||n.distance>3.1){say('Nothing close enough to fiddle with.');return}
 if(n.kind==='part'){const type=n.obj.userData.type;flags[type]=true;n.obj.visible=false;if(type==='engine')engineVisual.visible=true;if(type==='wheels'){spareVisual.visible=true;for(const w of wheels)w.visible=true}if(type==='battery')batteryVisual.visible=true;if(type==='fuel'){fuel=Math.min(100,fuel+55);$('#fuelText').textContent=Math.round(fuel)+'%'}say(({engine:'Engine bolted in. Sounds like a Saturday job.',wheels:'Four round things: an underrated upgrade.',battery:'Battery connected. The radio might live again.',fuel:'Fresh fuel. Try not to spill it on your shoes.'})[type]);refreshObjective();return}
 if(!completed()){say('Not quite ready. Find the missing parts first.');return}mode='drive';car.position.set(player.x,0,player.z);car.rotation.y=player.yaw;player.x=car.position.x;player.z=car.position.z;say('You are in. W accelerates, S brakes / reverses.');}
function updatePrompt(){const el=$('#prompt');if(!started){el.style.display='none';return}const n=nearest();if(mode==='drive'){el.innerHTML='<kbd>E</kbd> GET OUT';el.style.display='block';return}if(n&&n.distance<3.1){el.innerHTML=n.kind==='part'?`<kbd>E</kbd> PICK UP ${n.obj.userData.label}`:`<kbd>E</kbd> ${completed()?'GET IN':'CAR · NEED ALL FOUR PARTS'}`;el.style.display='block'}else el.style.display='none'}
function onKey(e,down){const k=e.key.toLowerCase();keys[k]=down;if(['w','a','s','d',' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();if(down&&!e.repeat&&k==='e'&&started)interact();if(down&&!e.repeat&&k==='escape'&&document.pointerLockElement)document.exitPointerLock()}
addEventListener('keydown',e=>onKey(e,true));addEventListener('keyup',e=>onKey(e,false));
$('#start').addEventListener('click',()=>{started=true;$('#intro').style.display='none';$('#hud').style.display='block';$('#crosshair').style.display='block';refreshObjective();renderer.domElement.requestPointerLock?.()});
renderer.domElement.addEventListener('click',()=>{if(started&&mode==='walk'&&innerWidth>700&&!document.pointerLockElement)renderer.domElement.requestPointerLock?.()});
document.addEventListener('mousemove',e=>{if(document.pointerLockElement===renderer.domElement&&mode==='walk'){player.yaw-=e.movementX*.0022;player.pitch=Math.max(-.72,Math.min(.6,player.pitch-e.movementY*.0018))}});
let touchX=0,touchY=0;renderer.domElement.addEventListener('pointerdown',e=>{if(e.pointerType!=='mouse'){touchX=e.clientX;touchY=e.clientY}});renderer.domElement.addEventListener('pointermove',e=>{if(e.pointerType!=='mouse'&&e.buttons&&mode==='walk'){player.yaw-=(e.clientX-touchX)*.006;player.pitch=Math.max(-.6,Math.min(.5,player.pitch-(e.clientY-touchY)*.004));touchX=e.clientX;touchY=e.clientY}});
for(const b of document.querySelectorAll('[data-key]')){const k=b.dataset.key;b.addEventListener('pointerdown',e=>{e.preventDefault();keys[k]=true;b.classList.add('on');b.setPointerCapture(e.pointerId)});for(const ev of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(ev,()=>{keys[k]=false;b.classList.remove('on')})}
$('#interactBtn').addEventListener('pointerdown',e=>{e.preventDefault();interact()});$('#brakeBtn').addEventListener('pointerdown',e=>{e.preventDefault();keys.s=true});for(const ev of ['pointerup','pointercancel','lostpointercapture'])$('#brakeBtn').addEventListener(ev,()=>keys.s=false);

